SELECT *
FROM products
LIMIT 10;

SELECT first_name, last_name, email
FROM customers
WHERE country = 'Mexico';

SELECT order_id, customer_id, ordered_at, status
FROM orders
WHERE status = 'delivered';

SELECT product_id, name, category_id
FROM products
WHERE category_id != 1;

SELECT first_name, last_name, country
FROM customers
WHERE country != 'Spain';

SELECT name, price
FROM products
WHERE price > 100;

SELECT first_name, last_name, email
FROM customers
ORDER BY last_name ASC, first_name ASC;

SELECT name, price
FROM products
ORDER BY price DESC;

SELECT order_id, ordered_at, status
FROM orders
ORDER BY ordered_at DESC, status ASC, order_id ASC;

SELECT c.first_name, c.last_name, c.country, c.city
FROM customers AS c
WHERE c.country = 'Mexico';
